export function verifyPublisherTree(root,c){const run=(...args)=>execFileSync('git',args,{cwd:root,encoding:'utf8'}).trim();const head=run('rev-parse','HEAD');assert.match(head,/^[0-9a-f]{40}$/);run('merge-base','--is-ancestor',c.publisherBaseSHA,head);const changed=run('diff','--name-only',c.publisherBaseSHA,head).split('\n').filter(Boolean).sort();assert.deepEqual(changed,[...c.newPublisherPaths].sort(),'EXACT_MAIN_SEVEN_PATH_TREE');assert.equal(run('diff','--name-only','HEAD'),'','CLEAN_PUBLISHER');for(const p of c.newPublisherPaths)assert.equal(sha(execFileSync('git',['show',head+':'+p],{cwd:root})),sha(fs.readFileSync(path.join(root,p))),'COMMITTED_PUBLISHER_FILE '+p);return head;}
