 assert.ok(metadata!==null&&typeof metadata==='object'&&!Array.isArray(metadata),'PLAIN_NATIVE_REFERENCE_METADATA_OBJECT');assert.equal(Object.getPrototypeOf(metadata),Object.prototype,'PLAIN_NATIVE_REFERENCE_METADATA_OBJECT');
