  const value=JSON.parse(text);assert.equal(canonical(value),text,'CANONICAL_REFERENCE_METADATA_TEXT '+name);assert.equal(nativeDigest(value),expected,'FIXED_DECODED_REFERENCE_METADATA '+name);decoded[name]=value;
