 const contracts=Object.fromEntries(blocks.map(b=>[b.id,Object.fromEntries(['construction_design_hash','layout_design_hash','learner_copy_hash'].filter(k=>b[k]).map(k=>[k,b[k]]))]));if(Object.values(contracts).some(v=>Object.keys(v).length)&&facets.some(f=>['math','design','render'].includes(f)))base.construction_layout_contracts=contracts;
