function validateTechnical(t,get,c,publisherFiles){const s=t.state;assert.ok(s&&t.approval&&t.patchIntentCount===1&&t.patchAppliedCount===1,'ACTUAL_APPROVED_APPLIED_TECHNICAL_SEVEN');assert.match(s.plan.proposal.hash,/^[0-9a-f]{64}$/);assert.equal(s.candidate_sha,t.publisherSHA);assert.deepEqual(s.candidate_manifest,publisherFiles);assert.equal(Object.keys(s.claims).length,0);assert.equal(s.paused,false);for(const issue of Object.values(s.issues))assert.ok(issue.resolved_by);for(const x of Object.values(s.external))assert.ok(x.outcome);for(const node of Object.values(technicalNodes())){const r=s.results[node.id];assert.equal(r?.verdict,'PASS');assert.equal(r.input_hash,technicalInput(s,node),'CURRENT_CLOSED_TECHNICAL_INPUT '+node.id);assert.equal(get(r.artifact).verdict,'PASS');}return{proposalHash:s.plan.proposal.hash,approval:t.approval};}

export function validateNativeIntent(envelope,c,{publisherSHA,publisherFiles,producerRunID,producerAttempt}={}){
 assert.match(publisherSHA??'',/^[0-9a-f]{40}$/);assert.deepEqual(Object.keys(publisherFiles??{}).sort(),[...c.newPublisherPaths].sort());assert.ok(Number(producerRunID)>0&&Number(producerAttempt)>0);
 validateBuildAuthority(c);const a=currentAuthority(c),build=decodeBuildAuthority(c),seed=build.baseState;assert.equal(envelope.schemaVersion,'qf01-native-authority/2');assert.equal(nativeDigest(envelope.baseState),a.baseStateSHA256);const get=currentObjects(envelope.objects);for(const [ref,value]of Object.entries(build.objects))assert.deepEqual(get(ref),value,'PRESERVE_APPROVED_BUILD_OBJECT');const s=structuredClone(seed),fresh={},bound=new Set(),registered=new Map(),outputs=new Map(),completed=new Set(),actions={};let seq=a.anchor.events,previous=a.anchor.head,revision=a.anchor.events,approvalSeq=a.anchor.events,requiresAllSix=false;const technical={state:null,publisherSHA,producerRunID,producerAttempt,patchIntentCount:0,patchAppliedCount:0};const actionUsers={};
 const valid=(id,seen=new Set())=>{assert.ok(!seen.has(id),'NATIVE_DEPENDENCY_CYCLE');seen.add(id);if(!CURRENT_GATES.includes(id)){assert.deepEqual(s.results[id],seed.results[id],'UNCHANGED_EARLIER_NATIVE_DEPENDENCY '+id);return;}currentGate(s,id,a,get,{bound,registered,outputs,completed,seedMode:!fresh[id]&&!requiresAllSix&&CURRENT_GATES.indexOf(id)<3});for(const dep of a.nodes[id].depends_on)valid(dep,new Set(seen));};
 assert.ok(Array.isArray(envelope.events)&&envelope.events.length);for(const event of envelope.events){assert.equal(event.seq,++seq);assert.equal(event.previous,previous);const body={...event};delete body.hash;assert.equal(nativeDigest(body),event.hash,'NATIVE_EVENT_CHAIN');previous=event.hash;if(event.work===TECHNICAL_WORK){replayTechnical(event,technical,get,c,publisherFiles);continue;}if(event.work!==CURRENT_WORK)continue;const p=structuredClone(event.payload);
 switch(event.kind){
 case 'feedback_captured':throw Error('POST_SEED_FEEDBACK_REQUIRES_NEW_CURRENT_GATE_BINDING');
 case 'revised':throw Error('MATERIAL_HUMAN_PROPOSAL_MUST_REMAIN_C2_UNCHANGED');
 case 'user':s.users[p.id]=p;if(p.intent==='approve_proposal'){currentUser(p,s,{approval:true});assert.equal(p.proposal_hash,seed.plan.proposal.hash);}if(['authorize_merge','authorize_deploy'].includes(p.intent)){assert.equal(p.proposal_hash,s.plan.proposal.hash);assert.deepEqual(p.scope,s.plan.scope);assert.equal(p.candidate_sha,SOURCE);assert.ok(['conversation_transcribed','authenticated_connector'].includes(p.verification_level));assert.ok(p.quote?.trim()&&p.source_ref?.trim());actions[p.intent]=seq;actionUsers[p.intent]=p;}break;
 case 'candidate':assert.equal(p.sha,SOURCE);assert.deepEqual(p.manifest,a.candidateManifest);s.candidate_sha=p.sha;s.candidate_manifest=p.manifest;break;
 case 'release_bound':assert.equal(p.sha,SOURCE);assert.deepEqual(p.units,[CURRENT_UNIT]);s.release_versions[CURRENT_UNIT]=p.sha;break;
 case 'production_context':assert.deepEqual(p.context,seed.production_context);s.production_context=p.context;break;
 case 'block_context':assert.deepEqual({...s.block_contexts[p.block],...p.facets},seed.block_contexts[p.block]??{});break;
 case 'claimed':s.claims[p.node]=p;break;
 case 'claim_reconciled':delete s.claims[p.node];break;
 case 'result_reopened':delete s.results[p.node];delete fresh[p.node];break;
 case 'evidence':s.evidence[p.id]=p;break;
 case 'capability_bound':bound.add(p.node+'|'+p.receipt+'|'+p.input_hash);break;
 case 'team_task_registered':registered.set(p.registrationRef,p);break;
 case 'team_output_recorded':outputs.set(p.outputRef,p);break;
 case 'team_task_reconciled':if(p.status==='COMPLETED')completed.add(p.registrationRef);break;
 case 'paused':s.paused=p.value;break;
 case 'issue':s.issues[p.id]=p;break;
 case 'issue_resolved':assert.ok(s.issues[p.id]);s.issues[p.id].resolved_by=p.child;break;
 case 'result':{s.results[p.node]=p;delete s.claims[p.node];if(!CURRENT_GATES.includes(p.node))break;if(p.verdict!=='PASS'){delete fresh[p.node];break;}assert.ok(seq>revision);if(!p.node.startsWith('R04'))assert.ok(approvalSeq&&seq>approvalSeq,'CURRENT_GATE_AFTER_APPROVAL');currentGate(s,p.node,a,get,{bound,registered,outputs,completed});for(const dep of a.nodes[p.node].depends_on)valid(dep);fresh[p.node]=seq;break;}
 case 'external_intent':assert.ok(!s.external[p.id],'DUPLICATE_NATIVE_OPERATION');s.external[p.id]=p;break;
 case 'external_outcome':assert.ok(s.external[p.id]);s.external[p.id].outcome=p.outcome;break;
 case 'patch_intent':case 'patch_applied':case 'definition_migrated':case 'materialization_bound':case 'team_policy_adopted':throw Error('UNEXPECTED_POST_APPLY_CONTENT_OR_CORE_CHANGE');
 default:break;
 }}
 currentPlan(s.plan,seed);assert.ok(approvalSeq>=revision);assert.equal(s.candidate_sha,SOURCE);assert.deepEqual(s.candidate_manifest,a.candidateManifest);assert.equal(s.release_versions[CURRENT_UNIT],SOURCE);let last=revision;for(const id of(requiresAllSix?CURRENT_GATES:CURRENT_GATES.slice(3))){assert.ok(fresh[id]>last,'FRESH_ORDERED_GATE '+id);valid(id);last=fresh[id];}for(const action of ['authorize_merge','authorize_deploy'])assert.ok(actions[action]>revision&&actions[action]<fresh['G2_AUDIT@'+CURRENT_UNIT],'ACTUAL_CURRENT_ACTION '+action);
 const technicalProof=validateTechnical(technical,get,c,publisherFiles);for(const action of ['authorize_merge','authorize_deploy']){const u=actionUsers[action];assert.equal(u.reply_to,technicalProof.proposalHash,'EXACT_P019_ACTION_DOCUMENT');assert.equal(u.quote,technicalProof.approval.quote,'SAME_ACTUAL_AUTHORIZATION_MESSAGE');assert.equal(u.source_ref,technicalProof.approval.source_ref,'SAME_ACTUAL_AUTHORIZATION_PROVENANCE');assert.ok(actions[action]>technical.approvalSeq);}
 const e=envelope.events.at(-1);assert.equal(e.work,CURRENT_WORK);assert.equal(e.kind,'external_intent');assert.equal(e.payload.operation,'DEPLOY');assert.equal(e.payload.release_unit,CURRENT_UNIT);assert.equal(e.payload.request_hash,technicalProof.proposalHash);assert.ok(e.payload.id&&!s.external[e.payload.id].outcome);assert.ok(seq>last);assert.equal(Object.keys(s.claims).length,0);assert.equal(s.paused,false);return{operationID:e.payload.id,eventHash:e.hash,sourceSHA:SOURCE,work:CURRENT_WORK,releaseUnit:CURRENT_UNIT,proposalHash:technicalProof.proposalHash,materialProposalHash:s.plan.proposal.hash,technicalWork:TECHNICAL_WORK,publisherSHA,g2Artifact:s.results['G2_AUDIT@'+CURRENT_UNIT].artifact};
}

export async function hydrateNativeAuthority(ref,{request=fetch,token=process.env.GH_TOKEN??process.env.GITHUB_TOKEN}={}){
 assert.equal(ref.schemaVersion,'qf01-native-authority-blob-ref/1');assert.equal(ref.repository,'rrikunagasige-dot/kyotsu-step-web');assert.equal(ref.encoding,'gzip-base64');
 assert.match(ref.blobSHA??'',/^[0-9a-f]{40}$/);for(const k of ['blobSHA256','expandedSHA256'])assert.match(ref[k]??'',/^[0-9a-f]{64}$/);
 assert.ok(token,'AUTHENTICATED_NATIVE_BLOB_READ');
 const response=await request('https://api.github.com/repos/rrikunagasige-dot/kyotsu-step-web/git/blobs/'+ref.blobSHA,{redirect:'error',headers:{Accept:'application/vnd.github+json',Authorization:'Bearer '+token,'X-GitHub-Api-Version':'2022-11-28'},signal:AbortSignal.timeout(30000)});
 assert.equal(response.status,200,'NATIVE_BLOB_HTTP');const length=Number(response.headers?.get('content-length')??0);assert.ok(length<=8*1024*1024,'NATIVE_BLOB_RESPONSE_LIMIT');
 // Bound streamed bytes as well: absent/lying Content-Length never removes cap.
 const reader=response.body.getReader(),chunks=[];let total=0;for(;;){const {done,value}=await reader.read();if(done)break;total+=value.length;assert.ok(total<=8*1024*1024,'NATIVE_BLOB_RESPONSE_LIMIT');chunks.push(Buffer.from(value));}
 const payload=JSON.parse(Buffer.concat(chunks).toString('utf8'));assert.equal(payload.sha,ref.blobSHA);assert.equal(payload.encoding,'base64');assert.ok(Number.isInteger(payload.size)&&payload.size>0&&payload.size<=5*1024*1024,'NATIVE_BLOB_SIZE');
 const encoded=payload.content.replace(/\n/g,'');assert.match(encoded,/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/);const blob=Buffer.from(encoded,'base64');assert.equal(blob.length,payload.size);assert.equal(blob.toString('base64'),encoded);
 assert.equal(createHash('sha1').update(Buffer.concat([Buffer.from('blob '+blob.length+'\0'),blob])).digest('hex'),ref.blobSHA,'NATIVE_GIT_BLOB_SHA');assert.equal(sha(blob),ref.blobSHA256,'NATIVE_BLOB_SHA256');
 const text=blob.toString('ascii');assert.ok(blob.equals(Buffer.from(text,'ascii')),'NATIVE_GZIP_BASE64_ASCII');assert.match(text,/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/);const compressed=Buffer.from(text,'base64');assert.equal(compressed.toString('base64'),text);
 const expanded=gunzipSync(compressed,{maxOutputLength:20*1024*1024});assert.equal(sha(expanded),ref.expandedSHA256,'NATIVE_EXPANDED_SHA256');return JSON.parse(expanded.toString('utf8'));
}

export function verifyDownloadedArchive({zipPath,artifact,expectedFiles,exact}){assert.equal(sha(fs.readFileSync(zipPath)),'sha256:'===artifact.digest.slice(0,7)?artifact.digest.slice(7):assert.fail('EXPLICIT_ARCHIVE_DIGEST'),'ACTUAL_ARCHIVE_SHA256');const code=`import sys,json,zipfile,hashlib,pathlib,stat
expected=json.load(sys.stdin)
with zipfile.ZipFile(sys.argv[1])as z:
 names=z.namelist();assert len(names)==len(set(names)), 'DUPLICATE_ZIP_ENTRY'
 actual={}
 for info in z.infolist():
  p=pathlib.PurePosixPath(info.filename);assert not p.is_absolute() and '..'not in p.parts and '\\\\'not in info.filename and not stat.S_ISLNK(info.external_attr>>16), 'UNSAFE_ZIP_ENTRY'
  if not info.is_dir():actual[info.filename]=hashlib.sha256(z.read(info)).hexdigest()
 if sys.argv[2]=='exact':assert set(actual)==set(expected), 'EXACT_ZIP_ENTRIES'
 for p,h in expected.items():assert actual.get(p)==h, 'ZIP_FILE_BYTES '+p
`;execFileSync('python3',['-c',code,zipPath,exact?'exact':'subset'],{input:JSON.stringify(expectedFiles),stdio:['pipe','pipe','pipe']});return true;}
export async function awaitExactManifest({base,expectedSHA256,attempts=60,delayMs=250,requestTimeoutMs=1000}){assert.match(expectedSHA256,/^[0-9a-f]{64}$/);for(let i=0;i<attempts;i++){try{const r=await fetch(new URL('qf01-release.json',base),{cache:'no-store',signal:AbortSignal.timeout(requestTimeoutMs)});if(r.ok&&sha(Buffer.from(await r.arrayBuffer()))===expectedSHA256)return;}catch{}if(i+1<attempts)await new Promise(r=>setTimeout(r,delayMs));}assert.fail('EXACT_VERIFICATION_SERVER_NOT_READY');}
